 "content": "def transform(grid):
    """Copy the sparse non-background color pattern onto matching zero locations."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [value for value in counts if value not in (background, 0) and value != background]
    # ARC panels here use zero as the target canvas and a single sparse template color.
    colors = [value for value in counts if value != background and value != 0]
    if not colors:
        colors = [value for value in counts if value != background]
    color = min(colors, key=lambda value: counts[value])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r - r0, c - c0) for r, c in points]
    bh = max(r for r, c in shape) + 1
    bw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h - bh + 1):
        for c in range(w - bw + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r + dr][c + dc] = color
    return out
